'use client'
import type { CSSProperties } from 'react'
import { useControllable } from '@/react/hooks/useControllable'

// A value on a range (new, in the console's grammar): the meter's 4px track (console2.css .v2-meter: a hairline-grey
// track, ink up to the value) and a square 12px ink thumb, with the switch's red focus outline. It follows the pointer
// with no easing, since the hand is moving it; arrows step it, Page Up and Down by tens, Home and End to the ends. The
// whole 28px row takes the pointer (40px on phones). Show the value beside it in tabular figures. Vue's v-model is
// `value` with `onValueChange` (or `defaultValue` alone).
export interface SliderProps {
  label: string
  min?: number
  max?: number
  step?: number
  disabled?: boolean
  valueText?: string
  value?: number
  defaultValue?: number
  onValueChange?: (value: number) => void
  className?: string
}

export function Slider({ label, min = 0, max = 100, step = 1, disabled, valueText, value, defaultValue = 0, onValueChange, className }: SliderProps) {
  const [current, setCurrent] = useControllable(value, defaultValue, onValueChange)
  const share = max > min ? ((current - min) / (max - min)) * 100 : 0
  return (
    <>
      <style href="ds-slider" precedence="ds">{css}</style>
      <span data-ds="slider" className={className ? `ds-slider ${className}` : 'ds-slider'} style={{ '--p': `${share}%` } as CSSProperties} data-disabled={disabled || undefined}>
        <span className="ds-slider-track" aria-hidden="true"><span /></span>
        <input type="range" value={current} onChange={e => setCurrent(Number(e.target.value))} min={min} max={max} step={step} disabled={disabled} aria-label={label} aria-valuetext={valueText} />
      </span>
    </>
  )
}

export default Slider

const css = `
.ds-slider { position: relative; display: flex; width: 100%; height: var(--ds-size-control-sm); align-items: center; }
.ds-slider-track { position: absolute; right: 0; left: 0; height: 4px; background: var(--ds-color-edge); pointer-events: none; }
.ds-slider-track > span { display: block; width: var(--p); height: 100%; background: var(--ds-color-surface-inverse); }
.ds-slider[data-disabled] .ds-slider-track > span { background: var(--ds-color-fg-faint); }
.ds-slider > input { position: relative; width: 100%; height: 100%; margin: 0; background: transparent; appearance: none; cursor: pointer; }
.ds-slider > input:disabled { cursor: not-allowed; }
.ds-slider > input:focus-visible { outline: none; }
.ds-slider > input::-webkit-slider-runnable-track { height: 4px; background: transparent; }
.ds-slider > input::-moz-range-track { height: 4px; background: transparent; }
.ds-slider > input::-webkit-slider-thumb { width: 12px; height: 12px; margin-top: -4px; border: 0; border-radius: 0; background: var(--ds-color-surface-inverse); appearance: none; }
.ds-slider > input::-moz-range-thumb { width: 12px; height: 12px; border: 0; border-radius: 0; background: var(--ds-color-surface-inverse); }
.ds-slider > input:disabled::-webkit-slider-thumb { background: var(--ds-color-fg-faint); }
.ds-slider > input:disabled::-moz-range-thumb { background: var(--ds-color-fg-faint); }
.ds-slider > input:focus-visible::-webkit-slider-thumb { outline: var(--ds-border-focus) solid var(--ds-color-edge-accent); outline-offset: var(--ds-border-focus); }
.ds-slider > input:focus-visible::-moz-range-thumb { outline: var(--ds-border-focus) solid var(--ds-color-edge-accent); outline-offset: var(--ds-border-focus); }
@media (pointer: coarse), (max-width: 767px) { .ds-slider { height: var(--ds-size-control-touch); } }
`

'use client'
import { useCallback, useRef, useState } from 'react'

// Vue's defineModel in React: a value that is controlled when the caller passes it (value + onValueChange, as Radix
// does) and kept inside otherwise (defaultValue). setValue calls onChange either way.
export function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (value: T) => void) {
	const [inner, setInner] = useState<T>(defaultValue)
	const controlled = value !== undefined
	const current = controlled ? value : inner
	const ref = useRef(onChange)
	ref.current = onChange
	const set = useCallback((next: T) => {
		if (!controlled) setInner(next)
		ref.current?.(next)
	}, [controlled])
	return [current, set] as const
}

import { html, LitElement, type PropertyValues } from 'lit'
import { ifDefined } from 'lit/directives/if-defined.js'
import { live } from 'lit/directives/live.js'
import { styleMap } from 'lit/directives/style-map.js'
import { DsFormElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// Slider.vue as <conare-slider>: a value on a range (new, in the console's grammar): the meter's 4px track (console2.css
// .v2-meter: a hairline-grey track, ink up to the value) and a square 12px ink thumb, with the switch's red focus
// outline. It follows the pointer with no easing, since the hand is moving it; arrows step it, Page Up and Down by tens,
// Home and End to the ends. The whole 28px row takes the pointer (40px on phones). Show the value beside it in tabular
// figures. v-model is a numeric `value` with `input` (while it moves) and `change` (when it is let go), as a native
// range's. Form-associated: its `name` goes with the form.

/**
 * @summary A value on a range.
 * @fires input - While it moves (read `value`).
 * @fires change - When it is let go (read `value`).
 */
export class Slider extends DsFormElement {
	static styles = [DsFormElement.styles, styles]
	static shadowRootOptions = { ...LitElement.shadowRootOptions, delegatesFocus: true }
	static dsField = true
	static properties = {
		value: { type: Number },
		label: {},
		min: { type: Number },
		max: { type: Number },
		step: { type: Number },
		disabled: { type: Boolean, reflect: true },
		valueText: { attribute: 'value-text' },
		name: {},
	}

	value = 0
	/** The name for assistive tech. */
	label = ''
	min = 0
	max = 100
	step = 1
	disabled = false
	/** What a screen reader says for the value (0.40 for 40). */
	valueText?: string
	name?: string

	protected updated(changed: PropertyValues) {
		super.updated(changed)
		if (changed.has('value')) this.internals.setFormValue(String(this.value))
	}
	protected validityControl() {
		return this.renderRoot.querySelector<HTMLInputElement>('input')
	}
	formResetCallback() {
		this.value = Number(this.getAttribute('value') ?? 0)
	}
	private onInput(event: Event) {
		this.value = Number((event.target as HTMLInputElement).value)
	}
	// The inner change does not leave the shadow root: the element sends its own.
	private onChange() {
		this.dispatchEvent(new Event('change', { bubbles: true, composed: true }))
	}

	render() {
		const share = this.max > this.min ? ((this.value - this.min) / (this.max - this.min)) * 100 : 0
		return html`<span data-ds="slider" class="ds-slider" style=${styleMap({ '--p': `${share}%` })} data-disabled=${ifDefined(this.inactive ? 'true' : undefined)}>
			<span class="ds-slider-track" aria-hidden="true"><span></span></span>
			<input type="range" min=${this.min} max=${this.max} step=${this.step} .value=${live(String(this.value))} ?disabled=${this.inactive} aria-label=${this.label} aria-valuetext=${ifDefined(this.valueText)} @input=${this.onInput} @change=${this.onChange}>
		</span>`
	}
}

define('slider', Slider)

